package mypackage5an;

public class Patterns4 {

	public static void main(String[] args) {
		System.out.println("25WH1A05AN");
		// TODO Auto-generated method stub
		for(int i=0;i<=8;i++) {
			for(int j=1;j<i;j++) {
				System.out.print(j);
			}
			System.out.println();
		}
		for(int m=0;m<=7;m++) {
			for(int n=1;n<7-m;n++) {
				System.out.print(n);
			}
			System.out.println();
		}
	}

}
